-- TotK's old lines (each drawn from one marker's own list of points) as
-- real paths, generated from the site's data by a script: 100 Korok pairs
-- (one check: its Start korok, its Finish korok following; the two renamed
-- from Hidden Korok: Pair and Carry), 105 Korok
-- races (timed, from a start point to where the korok appears) and 7 dragon flights. The
-- dragons are listed; the koroks are official but unlisted: on the map and
-- opened from their markers, kept out of lists, the sitemap and feeds.
-- Each is created as Jess's, in its history. A marker's line is only
-- converted while it's still exactly as it was here (one edited since keeps
-- its line), and the old lines are kept in marker_path_backup for the
-- down migration before they're cleared.

CREATE TABLE IF NOT EXISTS `marker_path_backup` (`marker_id` INT NOT NULL PRIMARY KEY, `path` MEDIUMTEXT NOT NULL);


-- Dinraal's Flight Path (Depths) (dinraals-flight-path-depths)
SET @p = (SELECT id FROM `path` WHERE container_id = 21 AND slug = 'dinraals-flight-path-depths');

-- Dinraal's Flight Path (Surface) (dinraals-flight-path-surface)
SET @p = (SELECT id FROM `path` WHERE container_id = 21 AND slug = 'dinraals-flight-path-surface');

