-- The old lines, now paths, cleared (kept in marker_path_backup).
UPDATE `marker` m SET m.path = '' WHERE m.marker_category_id IN (2116, 2173) AND m.path <> '' AND EXISTS (SELECT 1 FROM `path_step` s JOIN `path` p ON p.id = s.path_id WHERE p.container_id = 21 AND p.user_id = 15 AND p.kind = 'single' AND s.marker_id = m.id);
